r"""
Crescopus - CrescoLedger disputes, entry history and the AI summary trial

  - Raise a dispute about one or more entries; they're locked (but still
    counted, flagged) until it's settled.
  - Both people give their side, with evidence links.
  - Optional neutral AI summary: 3 free per account, then Premium.
  - Either proposes a resolution; when the other agrees it's applied:
    keep, correct the amount/hours, void, or change Recoverable/Goodwill.
  - The raiser can withdraw; either can close it unresolved after 14 quiet days.
  - Every change to every entry is now recorded in its history.

HOW TO USE
  1. Save this file in your Crescopus project folder (next to wsgi.py).
  2. In PowerShell, in that folder, with your venv active:
         python apply_disputes.py
  3. Run sql/migration_ledger_disputes.sql in the Supabase SQL editor. Safe to re-run.
  4. Any file it replaces is copied first to _backup_apply_disputes\.

Your .env is never read or changed.
"""
import base64, os, shutil, sys

FILES = [
    ("sql/migration_ledger_disputes.sql", ""),
    ("app/ledger/routes.py", ""),
    ("app/ledger/disputes.py", ""),
    ("app/ledger/ai_summary.py", ""),
    ("app/templates/ledger/view.html", ""),
    ("app/templates/ledger/dispute_new.html", ""),
    ("app/templates/ledger/dispute_view.html", ""),
    ("app/templates/ledger/entry_history.html", ""),
    ("app/utils.py", ""),
    ("app/plans/routes.py", ""),
    ("app/templates/dashboard/index.html", ""),
    ("app/static/css/cresco-ui.css", ""),
    ("render.yaml", ""),
    ("env.example", "")
]
BACKUP = "_backup_apply_disputes"
NEXT = "run sql/migration_ledger_disputes.sql in the Supabase SQL editor, check ANTHROPIC_API_KEY is set in Render (and in your .env to try summaries locally), restart python wsgi.py, then commit and push."

def main():
    root = os.path.dirname(os.path.abspath(__file__))
    if not os.path.isfile(os.path.join(root, "app", "__init__.py")) or not os.path.isfile(os.path.join(root, "wsgi.py")):
        sys.exit("Stopped: put this file in the Crescopus project folder (next to wsgi.py and the app folder), then run it again.")
    backup = os.path.join(root, BACKUP)
    changed = 0
    for rel, b64 in FILES:
        path = os.path.join(root, *rel.split("/"))
        data = base64.b64decode(b64)
        status = "new     "
        if os.path.exists(path):
            with open(path, "rb") as fh:
                if fh.read() == data:
                    print("same     " + rel)
                    continue
            dest = os.path.join(backup, *rel.split("/"))
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            shutil.copy2(path, dest)
            status = "updated "
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as fh:
            fh.write(data)
        changed += 1
        print(status + " " + rel)
    print("\nDone - %d of %d files written." % (changed, len(FILES)))
    if os.path.isdir(backup):
        print("Originals of replaced files are in " + BACKUP + os.sep)
    if NEXT:
        print("Next: " + NEXT)

if __name__ == "__main__":
    main()
